<?php
use App\Models\{Article,User,WebsiteSetting}; use Illuminate\Foundation\Testing\RefreshDatabase; uses(RefreshDatabase::class); beforeEach(function(){file_put_contents(storage_path('app/installed'),now()->toIso8601String());WebsiteSetting::create(['site_name'=>'Test','site_url'=>'https://example.test','timezone'=>'UTC']);}); afterEach(fn()=>@unlink(storage_path('app/installed'))); test('article visibility and escaped body',function(){Article::factory()->create(['title'=>'Private']);$article=Article::factory()->published()->create(['title'=>'Public insight','slug'=>'public-insight','body'=>'<script>alert(1)</script>\n\nSafe']);$this->get('/insights')->assertSuccessful()->assertSee('Public insight')->assertDontSee('Private');$this->get('/insights/public-insight')->assertSuccessful()->assertSee('&lt;script&gt;',false)->assertDontSee('<script>',false);}); test('article admin and validation are protected',function(){$this->get('/content/articles')->assertRedirect('/login');$this->actingAs(User::factory()->create(['is_active'=>true]))->post('/content/articles',['title'=>'Bad','slug'=>'../bad','excerpt'=>'Required','body'=>'Text'])->assertSessionHasErrors('slug');}); test('future article stays private and due article is public',function(){Article::factory()->create(['slug'=>'future','status'=>'scheduled','scheduled_for'=>now()->addHour()]);Article::factory()->scheduledDue()->create(['slug'=>'due','title'=>'Due insight']);$this->get('/insights/future')->assertNotFound();$this->get('/insights/due')->assertSuccessful();});
